def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opps = 0
    rich_opps = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) > 300:
                rich_opps += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opps += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive:
        return max(0.0, min(budget, 18.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if danger >= 5:
        bid = max(62.0, max_prev + 3.0)
    elif danger >= 3:
        bid = max(50.0, avg_prev + 4.0)
    else:
        if scarcity == 2:
            bid = max(34.0, avg_prev + 2.0)
        elif scarcity == 1:
            bid = max(24.0, avg_prev * 0.55)
        else:
            bid = 14.0

    if rich_opps >= 1 and scarcity >= 1:
        bid += 4.0
    if urgent_opps >= 2 and danger <= 2:
        bid -= 4.0

    if max_prev >= 120 and danger <= 2:
        bid = min(bid, 22.0)
    elif max_prev >= 80 and scarcity == 0 and danger <= 2:
        bid = min(bid, 18.0)

    if day >= 8:
        if hp >= 6 and budget < 120:
            bid *= 0.8
        elif hp <= 4:
            bid = max(bid, 55.0)

    if budget < 50:
        bid = min(bid, max(8.0, budget * 0.55))
    elif budget < 120:
        bid = min(bid, budget * 0.7)

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace only
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how tight the market is: higher when supply is closer to WATER_REQ
    # supply in [15,25] => ratio in [1.67,2.78]
    ratio = supply / float(WATER_REQ)
    tightness = 1.0 / max(1.0, ratio)  # higher when supply smaller

    # If opponents previously bid very high, raise pressure; otherwise bid to beat typical bids.
    # Use a budget-aware cap to avoid repeating Cindy-like death by depletion.
    budget_cap = budget
    if hp <= 2 or no_water_days >= 2:
        base = DAILY_SALARY * (0.85 + 0.1 * tightness)
    else:
        base = DAILY_SALARY * (0.6 + 0.25 * tightness)

    # If someone was bidding near the top yesterday, match/beat slightly.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        bid = min(budget_cap, max(base, highest_prev_bid * 0.92 + 2.0))
    else:
        # If highest was moderate, bid somewhat above it to improve chance without overpay.
        bid = min(budget_cap, max(base, highest_prev_bid * 0.75 + 10.0 * tightness))

    # Hard safety: never bid more than what keeps at least one day of salary in reserve if possible
    # (prevents extreme depletion).
    reserve = DAILY_SALARY * 0.2
    if budget > reserve:
        bid = min(bid, budget - reserve)

    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 40.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if prev_bids:
        max_prev = max(prev_bids)
        target = max_prev * 0.95
        if supply < 18:
            target = max_prev * 1.05
        return min(my_status['budget'], max(60.0, target))

    return min(my_status['budget'], 75.0)
